    wire logic signed [17:0] n2_1 = l2n1_w17;
    wire logic signed [15:0] l2n2_w1 = 16'($signed({1'b0, n1_0})) <<< 7;
    wire logic signed [15:0] l2n2_w2 = 16'($signed({1'b0, n1_1})) <<< 7;
    wire logic signed [15:0] l2n2_w3 = 16'($signed({1'b0, n1_2})) <<< 7;
    wire logic signed [15:0] l2n2_w4 = 16'($signed({1'b0, n1_3})) <<< 7;
    wire logic signed [15:0] l2n2_w5 = 16'($signed({1'b0, n1_4})) <<< 7;
    wire logic signed [14:0] l2n2_w6 = 15'($signed({1'b0, n1_5})) <<< 6;
    wire logic signed [15:0] l2n2_w7 = 16'($signed({1'b0, n1_6})) <<< 7;
    wire logic signed [15:0] l2n2_w8 = 16'($signed({1'b0, n1_7})) <<< 7;
    wire logic signed [11:0] l2n2_w9 = 12'sd1972;
    wire logic signed [16:0] l2n2_w10 = 17'(l2n2_w1) + 17'(l2n2_w2);
    wire logic signed [16:0] l2n2_w11 = 17'(l2n2_w3) + 17'(l2n2_w4);
    wire logic signed [15:0] l2n2_w12 = 16'(l2n2_w6) - 16'(l2n2_w5);
    wire logic signed [15:0] l2n2_w13 = 16'(l2n2_w7) - 16'(l2n2_w8);
    wire logic signed [16:0] l2n2_w14 = 17'(l2n2_w10) - 17'(l2n2_w11);
    wire logic signed [16:0] l2n2_w15 = 17'(l2n2_w12) + 17'(l2n2_w13);
    wire logic signed [17:0] l2n2_w16 = 18'(l2n2_w14) + 18'(l2n2_w15);
    wire logic signed [17:0] l2n2_w17 = 18'(l2n2_w16) + 18'(l2n2_w9);
    wire logic signed [17:0] n2_2 = l2n2_w17;
    // class scores and argmax, ties to the lowest class index
    wire logic signed [18:0] s0 = 19'(n2_0);
    wire logic signed [18:0] s1 = 19'(n2_1);
    wire logic signed [18:0] s2 = 19'(n2_2);
    wire logic       ge10 = s1 > s0;
    wire logic signed [18:0] m01 = ge10 ? s1 : s0;
    wire logic [1:0] c01 = ge10 ? 2'd1 : 2'd0;
    wire logic [1:0] cls = (s2 > m01) ? 2'd2 : c01;
    logic [LATENCY-1:0] vpipe;
    always_ff @(posedge clk) begin
        out_cls <= cls;
        if (rst) vpipe <= '0; else vpipe <= in_v;
    end
    assign out_v = vpipe[LATENCY-1];
endmodule
`default_nettype wire
